What will this Observer design pattern code print?

import java.util.*;
class Subject {
    private List<Observer> observers = new ArrayList<>();
    private int state = 0;
    public void addObserver(Observer o) { observers.add(o); }
    public void setState(int state) { this.state = state; notifyObservers(); }
    private void notifyObservers() { for(Observer o : observers) o.update(state); }
}
interface Observer { void update(int state); }
class ConcreteObserver implements Observer {
    public void update(int state) { System.out.print(state); }
}

Subject subject = new Subject();
subject.addObserver(new ConcreteObserver());
subject.addObserver(new ConcreteObserver());
subject.setState(5);

